const trigger = $('Trigger Telegram').item.json;
const chatId = trigger.message.chat.id;
const text = trigger.message.text || '';
const row = $input.first().json;
const count = Number(row.company_count || 0);

let reply;
if (count === 0) {
  reply = `🤖 Hola. Tu chat de Telegram (chat_id: ${chatId}) todavía no está vinculado a ninguna empresa. Pídele a Rafael que lo conecte en company_social_accounts.`;
} else {
  reply = `🟢 Conectado a: ${row.companies_matched}.\n\nRecibí tu mensaje: "${text}"\n\n(El menú diario y las respuestas con IA llegan en la Fase 4.)`;
}

return [{ json: { chat_id: chatId, reply_text: reply, company_count: count } }];
